contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mintAmount, uint256 burnAmount) public {
        require(mintAmount > 0 || burnAmount > 0);

        c.mint(address(this), mintAmount);
        uint256 supplyAfterMint = c.totalSupply();
        uint256 balAfterMint = c.balanceOf(address(this));
        uint8 decsAfterMint = c.decimals();

        c.burn(address(this), burnAmount);
        uint256 supplyAfterBurn = c.totalSupply();
        uint256 balAfterBurn = c.balanceOf(address(this));

        assert(supplyAfterMint == 0 || supplyAfterMint >= mintAmount);
        assert(balAfterMint == mintAmount);
        assert(decsAfterMint == c.decimals());
        assert(supplyAfterBurn <= supplyAfterMint);
        assert(balAfterBurn == mintAmount - burnAmount);
        assert(c.allowance(address(this), address(this)) == c.allowance(address(this), address(this)));
        assert(c.totalSupply() == supplyAfterBurn);
    }
}

