contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint128 newPrice, bool tryRely, bool tryDeny, bool tryUpdatePrice) public {
        require(user != address(this));

        uint256 wardBefore = c.wards(user);
        uint128 priceBefore = c.latestPrice();

        bool relyReverted;
        if (tryRely) {
            try c.rely(user) {
                relyReverted = false;
            } catch {
                relyReverted = true;
            }
        }

        bool denyReverted;
        if (tryDeny) {
            try c.deny(user) {
                denyReverted = false;
            } catch {
                denyReverted = true;
            }
        }

        bool updatePriceReverted;
        if (tryUpdatePrice) {
            try c.updatePrice(newPrice) {
                updatePriceReverted = false;
            } catch {
                updatePriceReverted = true;
            }
        }

        uint256 wardAfter = c.wards(user);
        uint128 priceAfter = c.latestPrice();

        assert(
            (wardBefore == wardAfter || relyReverted || denyReverted) &&
            (priceBefore == priceAfter || updatePriceReverted)
        );
    }
}

