contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address user, uint256 value) public payable {
        // caller is the msg.sender for the direct call below; we act as c's deployer, who is a ward
        // inspect c's public state before
try
        uint256 wardsBeforeCaller = c.wards(caller);
        uint256 wardsBeforeUser = c.wards(user);

        // try to call rely directly as msg.sender == address(this); if address(this) is not a ward this reverts
        bool relyReverted;
        if (wardsBeforeCaller == 0) {
            try c.rely(user) { relyReverted = false; } catch { relyReverted = true; }
        }

        uint256 wardsAfterCaller = c.wards(caller);
        uint256 wardsAfterUser = c.wards(user);

        // general rule: a non-ward caller cannot change any ward mapping via rely
        assert(wardsBeforeUser == wardsAfterUser && wardsBeforeCaller == wardsAfterCaller);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user) public payable {
        // c.wards is public, so it has an auto-generated getter.
        // msg.sender is this contract, which is not necessarily a ward.
        uint256 wardsBeforeUser = c.wards(user);

        bool reverted;
        try c.rely(user) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 wardsAfterUser = c.wards(user);

        // The general rule: a call to rely(user) from a non-ward either reverts or,
        // if it succeeds, then caller must have been a ward and user's ward value becomes 1.
        // Equivalently, if the caller is not a ward (which we represent by the call reverting),
        // the ward status of user is unchanged.
        // Since we cannot read the caller's ward status directly through a public getter
        // without knowing the caller address, we express the rule as: a successful rely
        // always sets wards[user] to 1, and a reverting rely leaves wards[user] unchanged.
        assert(reverted ? wardsAfterUser == wardsBeforeUser : wardsAfterUser == 1);
    }

    receive() external payable {}
}

