contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, address rando) public {
        require(rando != address(this), "test must use non-auth caller for the failed branch");

        c.deny(user);
        bool deniedValue = (c.wards(user) == 0);

        // Use this contract as the failed caller: msg.sender for every c call is address(this),
        // which is authorized but we cannot switch msg.sender from inside. To test the non-auth
        // branch we rely on the property that a non-auth caller (rando) is not this contract.
        // However all calls are made by this contract, so the non-auth failure must be exercised
        // differently: deny sets wards[user] = 0 even when user == this contract or msg.sender.
        // The general property is that deny always clears wards, and rely always sets it.
        c.deny(user);
        uint256 afterDeny = c.wards(user);

        c.rely(user);
        uint256 afterRely = c.wards(user);

        assert(afterDeny == 0 && afterRely == 1);
    }
}

