contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint128 newPrice) public {
        // Snapshot observable price and ward status of the test contract (msg.sender for all c calls).
        uint128 before = c.latestPrice();
        uint256 wardStatus = c.wards(address(this));

        // Attempt the auth-gated state change from this test contract, which deployed c
        // but was not granted a ward after deployment (constructor wards deployer? it does wards[msg.sender]=1 only).
        bool reverted;
        try c.updatePrice(newPrice) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 after = c.latestPrice();

        if (wardStatus == 0) {
            // Non-ward: must revert and leave price untouched.
            assert(reverted && after == before);
        } else {
            // Ward: must succeed and set the price exactly.
            assert(!reverted && after == newPrice);
        }
    }
}

