        // Snapshot observable state before the deciding call.
        uint128 priceBefore = c.latestPrice();
        uint256 updateBefore = c.lastPriceUpdate();
        uint256 wardsCaller = c.wards(caller);

        // The deciding call: can succeed only if caller is a ward (auth modifier).
        bool reverted;
        try c.updatePrice(newPrice) { revert = false; } catch { revert = true; }

        if (!reverted) {
            // Success is only possible for an authorized ward.
            assert(wardsCaller == 1);
            assert(c.latestPrice() == newPrice);
            assert(c.lastPriceUpdate() == block.timestamp);
        } else {
            // Unauthorized calls must leave price state untouched.
            assert(c.latestPrice() == priceBefore);
            assert(c.lastPriceUpdate() == updateBefore);
        }

        // General rule independent of caller: after any call to updatePrice,
        // the price equals newPrice if and only if the call succeeded.
        assert((c.latestPrice() == newPrice) == !reverted);
        // And the timestamp equals block.timestamp iff the call succeeded.
        assert((c.lastPriceUpdate() == block.timestamp) == !reverted);
    }

    receive() external payable {}
}

