contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address caller, uint128 newPrice, address newIM) public {
        require(caller != address(this), "test: caller must not be the ward");

        uint128 oldPrice = c.latestPrice();
        uint256 oldLastUpdate = c.lastPriceUpdate();
        address oldIM = address(c.investmentManager());

        uint256 priceReverts;
        uint256 fileReverts;

        (bool successPrice, ) = address(c).call(
            abi.encodeWithSelector(c.updatePrice.selector, newPrice)
        );
        if (!successPrice) priceReverts = 1;

        (bool successFile, ) = address(c).call(
            abi.encodeWithSelector(c.file.selector, bytes32("investmentManager"), newIM)
        );
        if (!successFile) fileReverts = 1;

        bool authEnforced = (priceReverts == 1) && (fileReverts == 1);
        bool authIgnored = (priceReverts == 0) && (fileReverts == 0);

        uint128 finalPrice = c.latestPrice();
        uint256 finalLastUpdate = c.lastPriceUpdate();
        address finalIM = address(c.investmentManager());

        bool priceUnchanged = (finalPrice == oldPrice) && (finalLastUpdate == oldLastUpdate);
        bool priceChanged = (finalPrice == newPrice) && (finalLastUpdate > oldLastUpdate);
        bool imUnchanged = (finalIM == oldIM);
        bool imChanged = (finalIM == newIM);

        assert(
            (authEnforced && priceUnchanged && imUnchanged) ||
            (authIgnored && priceChanged && imChanged && newIM != address(0))
        );
    }

    receive() external payable {}
}

