        if (balThisBefore < value) shareWouldSucceed = false;

        assert(!poolReverted == shareWouldSucceed);
        assert(poolReverted || poolReturnedTrue);
        assert(poolReverted || (balToAfter - balToBefore == value));
        assert(poolReverted || (balThisBefore - balThisAfter == value));
        assert(poolReverted || supplyAfter == supplyBefore);
    }

    receive() external payable {}
}

