        string memory shareSymbol = c.share().symbol();

        uint8 poolDecimals = c.decimals();
        uint8 shareDecimals = c.share().decimals();

        bool approved = false;
        try c.approve(spender, value) returns (bool ok) {
            approved = ok;
        } catch {
            approved = false;
        }

        uint256 afterPoolAllowance = c.allowance(account, spender);
        uint256 afterShareAllowance = c.share().allowance(account, spender);

        assert(
            keccak256(bytes(poolName)) == keccak256(bytes(shareName))
                && keccak256(bytes(poolSymbol)) == keccak256(bytes(shareSymbol))
                && poolDecimals == shareDecimals
                && poolTotalSupply == shareTotalSupply
                && poolBalance == shareBalance
                && poolAllowance == shareAllowance
                && afterPoolAllowance == afterShareAllowance
                && afterPoolAllowance == (approved ? value : poolAllowance)
        );
    }

    receive() external payable {}
}

