contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address user, bool doRely) public payable {
        bool isWardBefore = c.wards(user) == 1;
        bool authSuccess = c.wards(address(this)) == 1;
        require(authSuccess, "test not ward");
        if (doRely) {
            c.rely(user);
        } else {
            c.deny(user);
        }
        bool isWardAfter = c.wards(user) == 1;
        assert(doRely ? isWardAfter : !isWardAfter);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, bool doRely) public payable {
        require(c.wards(address(this)) == 1, "test not ward");

        bool before = c.wards(user) == 1;

        if (doRely) {
            c.rely(user);
