contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address user) public payable {
        require(user != address(0), "zero user");
        require(c.wards(address(this)) == 1, "test not ward");

        bool wasWard = c.wards(user) == 1;
        bool relyReverted;
        try c.rely(user) { relyReverted = false; } catch { relyReverted = true; }
        require(!relyReverted, "rely unexpectedly reverted");
        require(c.wards(user) == 1, "rely did not set ward");

        bool denyReverted;
        try c.deny(user) { denyReverted = false; } catch { denyReverted = true; }
        require(!denyReverted, "deny unexpectedly reverted");
        require(c.wards(user) == 0, "deny did not clear ward");

        assert(wasWard || !wasWard);
    }

    receive() external payable {}
}

