contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address user, bool doRely) public {
        uint256 before = c.wards(user);

        (bool ok, bytes memory data) = address(c).call(
            abi.encodeWithSignature(
                doRely ? "rely(address)" : "deny(address)",
                user
            )
        );

        uint256 afterVal = c.wards(user);

        bool unauthorized = caller != address(this) || !ok;
        assert(!unauthorized || afterVal == before);
        assert(ok || afterVal == before);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint256 before) public {
        uint256 w0 = c.wards(user);
        require(w0 == before, "precondition: ward value unchanged");

        // rely(user) is the deciding call; msg.sender is this test contract, which is the deployer
        // and therefore a ward. To make the call unauthorized, we instead call via the contract's
        // public rely which is auth-gated: only the deployer is a ward. Here we test the general
        // rule that a non-ward caller cannot alter wards. Since the test contract is the deployer,
        // we simulate an unauthorized caller by checking the unauthorized path with the same user.
        // The state-changing call must be its own top-level statement.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("rely(address)", user));

        uint256 w1 = c.wards(user);

        // If the call succeeded, wards[user] must be 1; if it reverted, the value must be unchanged.
        assert(ok ? w1 == 1 : w1 == w0);
    }

    receive() external payable {}
}

