contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 amount, address owner, address spender) public {
        bool transferReverted;
        bool approveReverted;
        bool transferFromReverted;
        bool transferReturned;
        bool approveReturned;
        bool transferFromReturned;

        try c.transfer(to, amount) returns (bool ret) {
            transferReturned = ret;
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        try c.approve(spender, amount) returns (bool ret) {
            approveReturned = ret;
            approveReverted = false;
        } catch {
            approveReverted = true;
        }

        try c.transferFrom(owner, to, amount) returns (bool ret) {
            transferFromReturned = ret;
            transferFromReverted = false;
        } catch {
            transferFromReverted = true;
        }

        bool expectedTransferReverted;
        bool expectedApproveReverted;
        bool expectedTransferFromReverted;
        bool expectedTransferReturned;
        bool expectedApproveReturned;
        bool expectedTransferFromReturned;

        try c.share().transfer(to, amount) returns (bool ret) {
            expectedTransferReturned = ret;
            expectedTransferReverted = false;
        } catch {
            expectedTransferReverted = true;
        }

        try c.share().approve(spender, amount) returns (bool ret) {
            expectedApproveReturned = ret;
            expectedApproveReverted = false;
        } catch {
            expectedApproveReverted = true;
        }

        try c.share().transferFrom(owner, to, amount) returns (bool ret) {
            expectedTransferFromReturned = ret;
            expectedTransferFromReverted = false;
        } catch {
            expectedTransferFromReverted = true;
        }

        assert(
            transferReverted == expectedTransferReverted &&
            approveReverted == expectedApproveReverted &&
            transferFromReverted == expectedTransferFromReverted &&
            (!transferReverted ? transferReturned == expectedTransferReturned : true) &&
            (!approveReverted ? approveReturned == expectedApproveReturned : true) &&
            (!transferFromReverted ? transferFromReturned == expectedTransferFromReturned : true)
        );
    }
}
